    { "id": "1", "nome": "Ana Souza", "curso": "Engenharia de Software" },
    { "id": "2", "nome": "Bruno Lima", "curso": "Sistemas de Informação" }
  ]
}

const API_URL = "http://localhost:3001";

export async function listarAlunos() {
  const resposta = await fetch(`${API_URL}/alunos`);
  if (!resposta.ok) throw new Error("Falha ao carregar alunos");
  return resposta.json();
}

export async function criarAluno(aluno) {
  const resposta = await fetch(`${API_URL}/alunos`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(aluno),
  });
  if (!resposta.ok) throw new Error("Falha ao salvar aluno");
  return resposta.json();
}
